if (retval) {
	ictx->tx.busy = false;
	smp_rmb(); /* ensure later readers know we're not busy */
	pr_err_ratelimited("error submitting urb(%d)\n", retval);
} else {
	/* Wait for transmission to complete (or abort) */
	long ret_timeout;

	ret_timeout = wait_for_completion_interruptible_timeout(
			&ictx->tx.finished, msecs_to_jiffies(1000));
	if (!ret_timeout) { /* Timeout */
		usb_kill_urb(ictx->tx_urb);
		pr_err_ratelimited("packet tx timeout\n");
		retval = -ETIMEDOUT;
	} else if (ret_timeout < 0) { /* Interrupted */
		usb_kill_urb(ictx->tx_urb);
		pr_err_ratelimited("task interrupted\n");
		retval = ret_timeout;
	} else { /* Completed */
		retval = ictx->tx.status;
		if (retval)
			pr_err_ratelimited("packet tx failed (%d)\n", retval);
	}
	ictx->tx.busy = false;
}

